import java.util.Scanner;
public class Main {
 private static final Scanner scanner=new Scanner(System.in);private static final IntArray array=new IntArray(100);private static final IntStack stack=new IntStack(50);private static final IntQueue queue=new IntQueue(50);private static final IntLinkedList linkedList=new IntLinkedList();private static final SearchManager search=new SearchManager();private static final Graph graph=new Graph();private static final PerformanceManager performance=new PerformanceManager();
 public static void main(String[] args){seed();boolean running=true;while(running){mainMenu();int c=readInt("Enter your choice: ");switch(c){case 1->arrayMenu();case 2->stackMenu();case 3->queueMenu();case 4->listMenu();case 5->searchMenu();case 6->graphMenu();case 7->performanceMenu();case 8->performance.displayAllResults();case 9->running=false;default->System.out.println("Invalid choice. Please select 1-9.");}}System.out.println("\nThank you for using Data Structure & Graph Analyzer.");}
 private static void mainMenu(){System.out.println("\n=============================================");System.out.println("       DATA STRUCTURE & GRAPH ANALYZER");System.out.println("=============================================");System.out.println("1. Array Operations\n2. Stack Operations\n3. Queue Operations\n4. Linked List Operations\n5. Searching Operations\n6. Graph Operations\n7. Performance Comparison\n8. Display All Results\n9. Exit");}
 private static void arrayMenu(){boolean b=false;while(!b){System.out.println("\n--------------- ARRAY OPERATIONS ---------------");System.out.println("1. Insert\n2. Delete\n3. Search\n4. Display\n5. Return to Main Menu");switch(readInt("Enter your choice: ")){case 1->System.out.println(array.insert(readInt("Enter position (0-"+array.size()+"): "),readInt("Enter value: ")));case 2->System.out.println(array.delete(readInt("Enter position to delete: ")));case 3->{int p=array.search(readInt("Enter value to search: "));System.out.println(p>=0?"Value found at index "+p+".":"Value not found.");}case 4->array.display();case 5->b=true;default->System.out.println("Invalid choice.");}}}
 private static void stackMenu(){boolean b=false;while(!b){System.out.println("\n--------------- STACK OPERATIONS ---------------");System.out.println("1. Push\n2. Pop\n3. Peek\n4. Display\n5. Return to Main Menu");switch(readInt("Enter your choice: ")){case 1->System.out.println(stack.push(readInt("Enter value: ")));case 2->System.out.println(stack.pop());case 3->System.out.println(stack.peek());case 4->stack.display();case 5->b=true;default->System.out.println("Invalid choice.");}}}
 private static void queueMenu(){boolean b=false;while(!b){System.out.println("\n--------------- QUEUE OPERATIONS ---------------");System.out.println("1. Enqueue\n2. Dequeue\n3. Peek / Front\n4. Display\n5. Return to Main Menu");switch(readInt("Enter your choice: ")){case 1->System.out.println(queue.enqueue(readInt("Enter value: ")));case 2->System.out.println(queue.dequeue());case 3->System.out.println(queue.peek());case 4->queue.display();case 5->b=true;default->System.out.println("Invalid choice.");}}}
 private static void listMenu(){boolean b=false;while(!b){System.out.println("\n------------- LINKED LIST OPERATIONS -------------");System.out.println("1. Insert at Beginning\n2. Insert at End\n3. Delete\n4. Search\n5. Display\n6. Return to Main Menu");switch(readInt("Enter your choice: ")){case 1->System.out.println(linkedList.insertAtBeginning(readInt("Enter value: ")));case 2->System.out.println(linkedList.insertAtEnd(readInt("Enter value: ")));case 3->System.out.println(linkedList.delete(readInt("Enter value to delete: ")));case 4->{int p=linkedList.search(readInt("Enter value to search: "));System.out.println(p>=0?"Value found at position "+p+".":"Value not found.");}case 5->linkedList.display();case 6->b=true;default->System.out.println("Invalid choice.");}}}
 private static void searchMenu(){boolean b=false;while(!b){System.out.println("\n--------------- SEARCHING OPERATIONS ---------------");System.out.println("1. Linear Search\n2. Binary Search\n3. Compare Linear vs Binary\n4. Display Current Array\n5. Return to Main Menu");switch(readInt("Enter your choice: ")){case 1->{int[] d=array.toArray();if(d.length==0){System.out.println("Array is empty.");break;}search.linearSearch(d,readInt("Enter value: ")).display("Linear Search");}case 2->{int[] d=array.toArray();if(d.length==0){System.out.println("Array is empty.");break;}search.binarySearch(d,readInt("Enter value: ")).display("Binary Search");}case 3->compareSearch();case 4->array.display();case 5->b=true;default->System.out.println("Invalid choice.");}}}
 private static void compareSearch(){int[] d=array.toArray();if(d.length<2){System.out.println("Add at least two array values first.");return;}int target=readInt("Enter value to search: ");SearchComparison x=search.compareSearches(d,target);x.display();performance.addResult("Search","Linear Search",x.linear.steps,x.linear.timeNanos);performance.addResult("Search","Binary Search",x.binary.steps,x.binary.timeNanos);}
 private static void graphMenu(){boolean b=false;while(!b){System.out.println("\n--------------- GRAPH OPERATIONS ---------------");System.out.println("1. Add Vertex\n2. Add Edge\n3. Display Graph\n4. BFS Traversal\n5. DFS Traversal\n6. Return to Main Menu");switch(readInt("Enter your choice: ")){case 1->System.out.println(graph.addVertex(readInt("Enter vertex number: ")));case 2->System.out.println(graph.addEdge(readInt("Enter source vertex: "),readInt("Enter destination vertex: ")));case 3->graph.display();case 4->traverse(true);case 5->traverse(false);case 6->b=true;default->System.out.println("Invalid choice.");}}}
 private static void traverse(boolean bfs){TraversalResult r=bfs?graph.bfs(readInt("Enter starting vertex: ")):graph.dfs(readInt("Enter starting vertex: "));r.display(bfs?"BFS Traversal":"DFS Traversal");if(r.success)performance.addResult("Graph Traversal",bfs?"BFS":"DFS",r.steps,r.timeNanos);}
 private static void performanceMenu(){boolean b=false;while(!b){System.out.println("\n------------- PERFORMANCE COMPARISON -------------");System.out.println("1. Compare Linear and Binary Search\n2. Compare BFS and DFS\n3. Display Performance Results\n4. Complexity Explanation\n5. Return to Main Menu");switch(readInt("Enter your choice: ")){case 1->compareSearch();case 2->compareGraph();case 3->performance.displayAllResults();case 4->performance.displayComplexityExplanation();case 5->b=true;default->System.out.println("Invalid choice.");}}}
 private static void compareGraph(){if(graph.vertexCount()==0){System.out.println("Add graph vertices first.");return;}int start=readInt("Enter starting vertex: ");TraversalResult b=graph.bfs(start),d=graph.dfs(start);b.display("BFS Traversal");d.display("DFS Traversal");if(b.success)performance.addResult("Graph Traversal","BFS",b.steps,b.timeNanos);if(d.success)performance.addResult("Graph Traversal","DFS",d.steps,d.timeNanos);}
 private static void seed(){int[] a={25,10,40,15,30};for(int i=0;i<a.length;i++)array.insert(i,a[i]);stack.push(10);stack.push(20);stack.push(30);queue.enqueue(100);queue.enqueue(200);queue.enqueue(300);linkedList.insertAtEnd(11);linkedList.insertAtEnd(22);linkedList.insertAtEnd(33);for(int v=1;v<=5;v++)graph.addVertex(v);graph.addEdge(1,2);graph.addEdge(1,3);graph.addEdge(2,4);graph.addEdge(3,4);graph.addEdge(4,5);}
 private static int readInt(String msg){while(true){System.out.print(msg);try{return Integer.parseInt(scanner.nextLine().trim());}catch(Exception e){System.out.println("Invalid input. Please enter a whole number.");}}}
}
